// TestScanRecordsDurationFromOpenHandleNotPath pins the fix for the defect
// where recordDuration stamped the cache row with a path-based stat
// (os.DirEntry.Info()) taken AFTER the header read, rather than a stat of the
// already-open file handle the duration was actually read from. A path-based
// stat is vulnerable to a tagger's write-tmp-then-rename swapping the file
// between the header read and the stat, banking a wrong duration under a new
// file's mtime/size, where it would validate as fresh forever.
//
// A live mid-scan rename race is impractical to force deterministically at
// the scheduler level, but the discriminating half of it -- "does the stamp
// come from the open fd or from re-resolving the path" -- is directly
// testable on Unix: an already-open fd keeps referring to its original inode
// even after the directory entry at that path is repointed by rename(2). So
// the probeFunc test seam (invoked immediately before recordDuration, see
// probeDuration) performs exactly that swap -- renaming a differently-sized
// replacement file over the scanned path -- between the header read and the
// stamp. A handle-derived stat (f.Stat(), the fix) is blind to the swap and
// still reports the ORIGINAL file's mtime/size; a path-derived stat
// (entry.Info(), the pre-fix bug) lazily re-Lstats the path at call time and
// picks up the REPLACEMENT file's mtime/size instead. This test asserts the
// former and, run against the pre-fix code, fails by observing the latter --
// see the git history for the empirical check.
func TestScanRecordsDurationFromOpenHandleNotPath(t *testing.T) {
	dir := t.TempDir()
	const sampleRate, totalSamples uint32 = 44100, 44100 * 210
	if err := testutil.WriteFLACFile(dir, "song.flac", sampleRate, totalSamples); err != nil {
		t.Fatalf("write fixture: %v", err)
	}
	path := filepath.Join(dir, "song.flac")

	wantInfo, err := os.Stat(path)
	if err != nil {
		t.Fatalf("stat fixture: %v", err)
	}

	store := &recordingDurationStore{}
	sc := NewScanner(WithDurationStore(store))

	// The swap happens inside probeFunc, which runs at exactly the point the
	// production code calls probeDuration -- immediately before recordDuration,
	// after the header (and open fd) already exist. Writing the replacement to
	// a temp name and renaming it over path (rather than truncating path in
	// place) is what makes the fd and the path diverge: rename repoints the
	// directory entry to a new inode while the already-open fd keeps its old
	// one, mirroring a tagger's write-tmp-then-rename.
	sc.probeFunc = func(p string) (int, error) {
		if p != path {
			return 210, nil
		}
		// A VORBIS_COMMENT block makes the replacement a different size than
		// the header-only original, so a path re-stat is distinguishable from
		// the handle stat by size alone.
		replacement := testutil.GenerateFLACExtended(sampleRate, totalSamples, map[string]string{"TITLE": "swapped"})
		tmp := path + ".swap"
		if err := os.WriteFile(tmp, replacement, 0o644); err != nil { //nolint:gosec // test fixture file
			return 0, fmt.Errorf("write replacement: %w", err)
		}
		if err := os.Rename(tmp, path); err != nil {
			return 0, fmt.Errorf("swap replacement over original: %w", err)
		}
		return 210, nil
	}

	results, err := sc.ScanLibrary(context.Background(), dir, ScanOptions{MaxDepth: 1, EnrichRecording: true})
	if err != nil {
		t.Fatalf("ScanLibrary: %v", err)
	}
	if len(results) != 1 {
		t.Fatalf("got %d results; want 1", len(results))
	}
	if len(store.paths) != 1 {
		t.Fatalf("recorded %d durations, want 1", len(store.paths))
	}

	// Sanity: confirm the swap actually changed what's on disk, else the test
	// proves nothing regardless of which stat source recordDuration used.
	replacedInfo, err := os.Stat(path)
	if err != nil {
		t.Fatalf("stat replacement: %v", err)
	}
	if replacedInfo.Size() == wantInfo.Size() {
		t.Fatalf("replacement file is the same size (%d) as the original; swap did not change the on-disk file, test cannot discriminate", replacedInfo.Size())
	}

	if got, want := store.sizes[0], wantInfo.Size(); got != want {
		t.Errorf("recorded size %d, want %d (size of the ORIGINAL file via the open handle, not the replacement at the same path)", got, want)
	}
	if got, want := store.mtimes[0], wantInfo.ModTime().UnixNano(); got != want {
		t.Errorf("recorded mtime %d, want %d (mtime of the ORIGINAL file via the open handle, not the replacement at the same path)", got, want)
	}
}

// TestScanRecordsNothingForZeroDuration directly exercises recordDuration's
// seconds<=0 guard, which scanDir relies on since it always calls
// recordDuration regardless of whether probeDuration succeeded (a parse
// failure degrades to duration 0, not a skipped call). Without this guard a
// zero/unparsable duration would bank a bogus row that reads as "measured
// zero-length" rather than "never read", so the guard is load-bearing, not
// defensive.
func TestScanRecordsNothingForZeroDuration(t *testing.T) {
	dir := t.TempDir()
	const sampleRate, totalSamples uint32 = 44100, 44100 * 210
	if err := testutil.WriteFLACFile(dir, "song.flac", sampleRate, totalSamples); err != nil {
		t.Fatalf("write fixture: %v", err)
	}

	store := &recordingDurationStore{}
	sc := NewScanner(WithDurationStore(store))
	// probeFunc stands in for a parse failure: probeDuration returns 0 with no
	// error, exactly what audioDuration degrades to on an unparsable header.
	sc.probeFunc = func(string) (int, error) { return 0, nil }

	results, err := sc.ScanLibrary(context.Background(), dir, ScanOptions{MaxDepth: 1, EnrichRecording: true})
	if err != nil {
		t.Fatalf("ScanLibrary: %v", err)
	}
	if len(results) != 1 {
		t.Fatalf("got %d results; want 1", len(results))
	}

	if len(store.paths) != 0 {
		t.Fatalf("recorded %d durations for a zero duration, want 0", len(store.paths))
	}
}

// lookupDurationStore is a minimal in-memory audiodur.Store stand-in keyed
// exactly like the real table (file_path is the whole key; mtime/size are
// stored alongside but not needed to prove the KEY-collapse property this
// test targets). It lets the test assert a real cache HIT, not just that two
// path strings look equal in prose.
type lookupDurationStore struct {
	rows map[string]int
}

func (s *lookupDurationStore) Record(_ context.Context, path string, _, _ int64, seconds int) error {
	if s.rows == nil {
		s.rows = make(map[string]int)
	}
	s.rows[path] = seconds
	return nil
}

// Lookup ignores mtime/size on purpose: file_path is the whole primary key in
// the real table, and the property this store exists to prove is KEY COLLAPSE
// (#643) -- that two spellings of one file resolve to a single row. Validating
// the stamp here would add a second reason for a miss and blur that signal.
func (s *lookupDurationStore) Lookup(_ context.Context, path string, _, _ int64) (int, bool, error) {
	seconds, ok := s.rows[path]
	return seconds, ok, nil
}

// TestScanLibrary_SymlinkedRootCollapsesToOneCanonicalKey exercises the #643
// fix end-to-end against a REAL symlinked directory layout, the deployment
// shape the issue was filed against (a container's /music mounted as a
// symlink to the array's real path, e.g. /music -> /mnt/array/music).
//
// It asserts two things a prose claim cannot stand in for:
//  1. The key the scanner actually writes is the canonical (symlink-resolved)
//     spelling, not the configured root's literal, possibly-symlinked one.
//  2. A lookup keyed the way a consumer would key it -- by canonicalizing
//     whatever source path it was handed, exactly as worker.recordDuration
//     now does via pathutil.CanonicalPath -- actually HITS the row the scan
//     wrote, whether that consumer's own path happened to be spelled via the
//     symlink or via the real target.
func TestScanLibrary_SymlinkedRootCollapsesToOneCanonicalKey(t *testing.T) {
	base := t.TempDir()
	realRoot := filepath.Join(base, "real-array-music")
	if err := os.MkdirAll(realRoot, 0o755); err != nil {
		t.Fatalf("mkdir real root: %v", err)
	}
	symlinkRoot := filepath.Join(base, "music")
	if err := os.Symlink(realRoot, symlinkRoot); err != nil {
		t.Skipf("symlinks unsupported here: %v", err)
	}

	const sampleRate, totalSamples uint32 = 44100, 44100 * 210
	if err := testutil.WriteFLACFile(realRoot, "song.flac", sampleRate, totalSamples); err != nil {
		t.Fatalf("write fixture: %v", err)
	}

	// The library root as an operator would configure it: the symlink path,
	// not the real target.
	store := &lookupDurationStore{}
	sc := NewScanner(WithDurationStore(store))
	results, err := sc.ScanLibrary(context.Background(), symlinkRoot, ScanOptions{MaxDepth: 1, EnrichRecording: true})
	if err != nil {
		t.Fatalf("ScanLibrary: %v", err)
	}
	if len(results) != 1 {
		t.Fatalf("got %d results; want 1", len(results))
	}

	wantKey, err := filepath.EvalSymlinks(filepath.Join(realRoot, "song.flac"))
	if err != nil {
		t.Fatalf("EvalSymlinks real path: %v", err)
	}
	if len(store.rows) != 1 {
		t.Fatalf("recorded %d rows, want 1", len(store.rows))
	}
	if _, ok := store.rows[wantKey]; !ok {
		t.Fatalf("scan wrote key(s) %v; want the canonical key %q present", mapKeys(store.rows), wantKey)
	}

	// Consumer side: a webhook-created item's SourcePath comes pre-resolved by
	// pathutil.ResolveWithinRoot (internal/server.confinedPayloadPath) against
	// the SAME configured (symlink) root.
	webhookSourcePath, ok := pathutil.ResolveWithinRoot(symlinkRoot, filepath.Join(symlinkRoot, "song.flac"))
	if !ok {
		t.Fatal("ResolveWithinRoot rejected the fixture path")
	}
	// A scan-enqueued item's SourcePath is the scanner's raw (unresolved)
	// ScanResult.FilePath -- the configured root's literal spelling, joined
	// with the walked filename (models.ScanResult is built from dir+file.Name,
	// not from the canonicalized recordDuration key).
	scanSourcePath := results[0].FilePath

	for name, consumerPath := range map[string]string{
		"webhook-resolved source path": webhookSourcePath,
		"scan-enqueued source path":    scanSourcePath,
	} {
		t.Run(name, func(t *testing.T) {
			// Mirrors worker.recordDuration's key derivation exactly
			// (pathutil.CanonicalPath), so this proves the worker capture site
			// and the scanner capture site land on the identical row.
			key := pathutil.CanonicalPath(consumerPath)
			// mtime/size are ignored by this store by design -- see its Lookup.
			seconds, hit, err := store.Lookup(context.Background(), key, 0, 0)
			if err != nil {
				t.Fatalf("Lookup: %v", err)
			}
			if !hit {
				t.Fatalf("consumer path %q (canonicalized to %q) missed the cache; scan wrote key %q", consumerPath, key, wantKey)
			}
			if seconds != 210 {
				t.Errorf("looked up %ds, want 210s", seconds)
			}
		})
	}
}

func mapKeys(m map[string]int) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	return keys
}

func TestReadAudioFactsReadsFullTagSet(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "track.mp3")
	// WriteAudioFileExtended is the existing testutil fixture helper for ID3-tagged audio.
	if err := testutil.WriteAudioFileExtended(dir, "track.mp3", "Test Artist", "Test Title", "Test Album", "", map[string]string{
		"TPE2": "Test Album Artist",
		"TCOM": "Test Composer",
		"TCON": "Test Genre",
		"TDRC": "1997",
		"TRCK": "3/12",
		"TPOS": "1/2",
		"TSRC": "US-TEST-97-00123",
	}, map[string]string{
		"musicbrainz_recordingid": "test-mbid-uuid",
	}); err != nil {
		t.Fatalf("WriteAudioFileExtended: %v", err)
	}

	got, err := ReadAudioFacts(path)
	if err != nil {
		t.Fatalf("ReadAudioFacts: %v", err)
	}

	if got.Artist != "Test Artist" {
		t.Errorf("Artist = %q, want %q", got.Artist, "Test Artist")
	}
	if got.AlbumArtist != "Test Album Artist" {
		t.Errorf("AlbumArtist = %q, want %q", got.AlbumArtist, "Test Album Artist")
	}
	if got.Title != "Test Title" {
		t.Errorf("Title = %q, want %q", got.Title, "Test Title")
	}
	if got.Album != "Test Album" {
		t.Errorf("Album = %q, want %q", got.Album, "Test Album")
	}
	if got.Composer != "Test Composer" {
		t.Errorf("Composer = %q, want %q", got.Composer, "Test Composer")
	}
	if got.Genre != "Test Genre" {
		t.Errorf("Genre = %q, want %q", got.Genre, "Test Genre")
	}
	if got.Year != 1997 {
		t.Errorf("Year = %d, want 1997", got.Year)
	}
	if got.TrackNo != 3 || got.TrackTotal != 12 {
		t.Errorf("Track = %d/%d, want 3/12", got.TrackNo, got.TrackTotal)
	}
	if got.DiscNo != 1 || got.DiscTotal != 2 {
		t.Errorf("Disc = %d/%d, want 1/2", got.DiscNo, got.DiscTotal)
	}
	if got.Format == "" || got.FileType == "" {
		t.Errorf("Format/FileType = %q/%q, want both non-empty", got.Format, got.FileType)
	}
	// Identity comes from the open handle's own Stat, never a path re-stat.
	if got.MTimeNano == 0 || got.SizeBytes == 0 {
		t.Errorf("MTimeNano/SizeBytes = %d/%d, want both non-zero", got.MTimeNano, got.SizeBytes)
	}
	if got.MBID != "test-mbid-uuid" {
		t.Errorf("MBID = %q, want %q", got.MBID, "test-mbid-uuid")
	}
	if got.ISRC != "US-TEST-97-00123" {
		t.Errorf("ISRC = %q, want %q", got.ISRC, "US-TEST-97-00123")
	}
}

func TestReadAudioFactsAbsentTagsAreSentinelsNotErrors(t *testing.T) {
	// A file with only the minimum tags: every other field must come back as its
	// documented zero-value sentinel, and this must NOT be an error.
	dir := t.TempDir()
	path := filepath.Join(dir, "track.mp3")
	if err := testutil.WriteAudioFile(dir, "track.mp3", "", "Only Title", "", ""); err != nil {
		t.Fatalf("WriteAudioFile: %v", err)
	}

	got, err := ReadAudioFacts(path)
	if err != nil {
		t.Fatalf("absent tags must not error: %v", err)
	}
	if got.Title != "Only Title" {
		t.Errorf("Title = %q, want %q", got.Title, "Only Title")
	}
	if got.Genre != "" || got.Composer != "" {
		t.Errorf("absent string tags = %q/%q, want empty sentinels", got.Genre, got.Composer)
	}
	if got.Year != 0 || got.TrackNo != 0 || got.DiscNo != 0 {
		t.Errorf("absent numeric tags = %d/%d/%d, want 0 sentinels", got.Year, got.TrackNo, got.DiscNo)
	}
}

func TestReadAudioFactsOpenFailureIsAnError(t *testing.T) {
	_, err := ReadAudioFacts(filepath.Join(t.TempDir(), "does-not-exist.mp3"))
	if err == nil {
		t.Fatal("a missing file must return an error, not a zero-value struct")
	}
}

func TestReadAudioFactsNeverExposesLyricsOrPicture(t *testing.T) {
	// Guards the deliberate exclusion: lyric text must never enter the DB
	// (copyright, and it would give the #538 extracted lane a self-ingestion
	// route), and cover art would dwarf every other column. A reflective check
	// so adding such a field later fails loudly rather than silently shipping.
	tp := reflect.TypeOf(AudioFacts{})
	for i := 0; i < tp.NumField(); i++ {
		name := strings.ToLower(tp.Field(i).Name)
		if strings.Contains(name, "lyric") || strings.Contains(name, "picture") || strings.Contains(name, "artwork") {
			t.Errorf("AudioFacts must not carry field %q: lyrics and cover art are deliberately excluded", tp.Field(i).Name)
		}
	}
}
